const parseUrl = value => require('url').parse(value, true);
const httpsOrigin = value => {
  const parsed = parseUrl(value);
  if (parsed.protocol !== 'https:' || !parsed.host || parsed.auth) throw new Error('Expected an HTTPS URL without embedded credentials');
  return parsed.protocol + '//' + parsed.host.toLowerCase();
};

